using System.IO;
using System.Text.Json;
namespace MRS;
internal static class FrequencyOrganizationTests
{
 internal static void Run(Action<bool,string> check)
 {
  string root=Path.Combine(Path.GetTempPath(),"mrs-organization-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);string file=Path.Combine(root,"library.json");var db=new FrequencyLibrary(file);var customFolder=new FrequencyItem{IsFolder=true,Name="My research"};db.Upsert(customFolder);
  FrequencyItem Channel(string variant,long hz,string name="DMR · CC 1")=>new(){ParentId=customFolder.Id,Name=name,FrequencyHz=hz,Protocols="DMR",SiteScope=$"DMR:{variant}:Unassigned at {PlanCsv.MHz(hz)}:Unresolved site",Signaling=$"{variant}; CC 1",Notes="Keep all my notes",Tags="Site channel discovery",OriginalFrequencyHz=hz+134};
  var generic=Channel("Unidentified system",453000000);var cap=Channel("Capacity Plus",453000000,"Cap+ · CC 1");var named=Channel("Unidentified system",451787500,"My named repeater");var ltr=new FrequencyItem{ParentId=customFolder.Id,Name="LTR · IDs unknown",FrequencyHz=451449500,Protocols="LTR",SiteScope="LTR:LTR Standard:Unassigned at 451.449500:Unresolved site",Signaling="LTR Standard; Area 1; Home 7",Notes="LTR note"};foreach(var c in new[]{generic,cap,named,ltr})db.Upsert(c);
  check(db.Organization==null,"Existing libraries retain legacy saving until organization is explicitly applied");string before=File.ReadAllText(file);var rules=new OrganizationRules();var plan=db.PreviewOrganization(rules,null,true,true,true);check(File.ReadAllText(file)==before&&db.Items.Count==5,"Organization preview does not write or mutate the library");
  string Parent(OrganizationPlan p,Guid id)=>p.Items.Single(i=>i.Id==p.Items.Single(c=>c.Id==id).ParentId).Name;
  string PathFor(IEnumerable<FrequencyItem> all,FrequencyItem c){var values=all.ToDictionary(i=>i.Id);var result=new List<string>();while(c.ParentId is {} parent){c=values[parent];result.Insert(0,c.Name);}return string.Join('/',result);}
  check(Parent(plan,generic.Id)=="CC 1"&&PathFor(plan.Items,plan.Items.Single(c=>c.Id==generic.Id))=="DMR/Generic DMR/CC 1","Unidentified DMR is grouped by subtype and color code without placeholder folders");check(PathFor(plan.Items,plan.Items.Single(c=>c.Id==cap.Id))=="DMR/Capacity Plus/CC 1","Capacity Plus remains separate from generic DMR with the same frequency/color code");
  check(plan.Items.Single(c=>c.Id==named.Id).Name==named.Name&&plan.Items.Single(c=>c.Id==ltr.Id).Name.Contains("Area 1 · Home 07"),"Custom labels survive while generic LTR labels gain decoded Area/Home");
  string backup=db.ApplyOrganization(plan);check(File.ReadAllText(backup)==before&&File.Exists(backup+".receipt.json"),"Applying creates an exact pre-change backup and rollback receipt");check(db.Items.Where(c=>!c.IsFolder).Select(c=>c.Id).ToHashSet().SetEquals(new[]{generic.Id,cap.Id,named.Id,ltr.Id}),"Organization retains every original channel ID without merging duplicate frequencies");foreach(var c in new[]{generic,cap,named,ltr})check((db.Items.Single(i=>i.Id==c.Id) with{Name=c.Name,ParentId=c.ParentId})==c,"Organization preserves all non-layout fields for "+c.Protocols+" "+c.Id.ToString("N")[..6]);
  check(db.Items.Any(c=>c.Id==customFolder.Id),"Empty user-created folders are preserved");var restarted=new FrequencyLibrary(file);check(restarted.Organization==rules,"Saving preferences survive restart in the same library");
  var incoming=new SiteChannelData("DMR",["DMR","Capacity Plus","Unassigned at 462.05","Unresolved site"],"DMR:Capacity Plus:Unassigned at 462.05:Unresolved site",462050000,"","Rest — last observed","Capacity Plus; CC 1",Evidence:"Provisional identity");restarted.SaveSiteChannels([incoming]);var saved=restarted.Items.Single(c=>!c.IsFolder&&c.FrequencyHz==462050000);check(PathFor(restarted.Items,saved)=="DMR/Capacity Plus/CC 1","A new automatic discovery uses the configured layout after restart");restarted.SaveSiteChannels([incoming]);check(restarted.Items.Count(c=>!c.IsFolder&&c.FrequencyHz==462050000)==1&&PathFor(restarted.Items,restarted.Items.Single(c=>c.Id==saved.Id))=="DMR/Capacity Plus/CC 1","Repeated auto-saves preserve organization without duplicate channels or placeholder folders");
  bool rejected=false;try{restarted.RollbackOrganization(backup);}catch(IOException){rejected=true;}check(rejected,"Rollback is blocked after subsequent discoveries to preserve newer data");
  var rollbackDb=new FrequencyLibrary(Path.Combine(root,"rollback.json"));rollbackDb.Upsert(generic with{ParentId=null});string old=File.ReadAllText(rollbackDb.LibraryPath);var review=rollbackDb.PreviewOrganization(rules,null,true,true,true);string restore=rollbackDb.ApplyOrganization(review);check(rollbackDb.OrganizationBackups().Contains(restore),"Organization backups are discoverable for the correct library");new FrequencyLibrary(rollbackDb.LibraryPath).RollbackOrganization(restore);check(File.ReadAllText(rollbackDb.LibraryPath)==old,"Rollback after restart restores the exact original library and preferences");
  var fresh=new FrequencyLibrary(Path.Combine(root,"fresh.json"));string emptyBackup=fresh.ApplyOrganization(fresh.PreviewOrganization(rules,null,false,true,true));fresh.RollbackOrganization(emptyBackup);check(fresh.Items.Count==0&&fresh.Organization==null,"A fresh library has a restorable empty baseline when first saving organization rules");
  var undoDb=new FrequencyLibrary(Path.Combine(root,"undo.json"));undoDb.Upsert(generic with{ParentId=null});undoDb.ApplyOrganization(undoDb.PreviewOrganization(rules,null,true,true,true));undoDb.Undo();check(undoDb.Organization==null&&undoDb.Items.Single().Id==generic.Id,"Undo restores the previous organization preferences as well as entries");
  var selectedDb=new FrequencyLibrary(Path.Combine(root,"selected.json"));selectedDb.Upsert(generic with{ParentId=null});selectedDb.Upsert(cap with{ParentId=null});var limited=selectedDb.PreviewOrganization(rules,[generic.Id],true,false,true);check(limited.Items.Single(c=>c.Id==cap.Id)==(cap with{ParentId=null})&&limited.Items.Single(c=>c.Id==generic.Id).ParentId!=null,"Selected-entry organization leaves unselected entries unchanged");
  rejected=false;try{selectedDb.PreviewOrganization(rules,[],true,true,true);}catch(IOException){rejected=true;}check(rejected,"An empty selected scope is rejected instead of becoming the whole library");
  foreach(string template in new[]{"{bogus}","../{cc}","{protocol}\\{cc}","{protocol"}){rejected=false;try{selectedDb.PreviewOrganization(rules with{Layout="Custom",FolderTemplate=template},null,true,true,true);}catch(IOException){rejected=true;}check(rejected,"Invalid organization template is rejected: "+template);}
  var custom=selectedDb.PreviewOrganization(rules with{Layout="Custom",FolderTemplate="Research/{cc}/{site}"},null,true,true,true);check(PathFor(custom.Items,custom.Items.Single(c=>c.Id==generic.Id))=="Research/CC 1","Custom templates omit unavailable fields without inventing site identity");
  var ambiguous=generic with{Id=Guid.NewGuid(),ParentId=null,Signaling="CC 1; CC 6"};selectedDb.Upsert(ambiguous);var held=selectedDb.PreviewOrganization(rules,null,true,true,true);check(held.Changes.Any(c=>c.Action=="Held")&&held.Items.Single(c=>c.Id==ambiguous.Id)==ambiguous,"Conflicting identifiers remain unmoved and explicitly held for review");
  var stale=selectedDb.PreviewOrganization(rules,null,true,true,true);selectedDb.Upsert(generic with{ParentId=null,Notes="Edited after preview"});rejected=false;try{selectedDb.ApplyOrganization(stale);}catch(IOException){rejected=true;}check(rejected,"Stale organization previews cannot overwrite later local edits");var external=new FrequencyLibrary(selectedDb.LibraryPath);var disk=external.PreviewOrganization(rules,null,true,true,true);selectedDb.Upsert(generic with{ParentId=null,Notes="Another writer"});rejected=false;try{external.ApplyOrganization(disk);}catch(IOException){rejected=true;}check(rejected&&new FrequencyLibrary(selectedDb.LibraryPath).Items.Single(c=>c.Id==generic.Id).Notes=="Another writer","Disk revision checks preserve another window's newer edit");
  var futureOnly=new FrequencyLibrary(Path.Combine(root,"future-only.json"));futureOnly.Upsert(generic with{ParentId=null});futureOnly.ApplyOrganization(futureOnly.PreviewOrganization(rules,null,false,true,true));check(futureOnly.Items.Single().ParentId==null&&futureOnly.Organization!=null,"Future-only configuration leaves existing entries untouched");
  var first=new SiteChannelData("DMR",["DMR","Unidentified system","Unassigned at 460.1","Unresolved site"],"DMR:Unidentified system:Unassigned at 460.1:Unresolved site",460100000,"","Observed carrier","DMR; CC 1",Evidence:"Provisional identity");futureOnly.SaveSiteChannels([first]);var original=futureOnly.Items.Single(c=>c.FrequencyHz==first.Hz);futureOnly.SaveSiteChannels([first with{Scope="DMR:DMR Tier III:Network 5:Site 1",Folders=["DMR","DMR Tier III","Network 5","Site 1"],Identifiers="DMR Tier III; Network 5; Site 1; CC 1",Evidence="Observed"}]);var refined=futureOnly.Items.Single(c=>c.Id==original.Id);check(PathFor(futureOnly.Items,refined)=="DMR/DMR Tier III/Network 5/Site 1"&&refined.FrequencyHz==original.FrequencyHz,"Later decoded system/site identity moves the same auto-saved record without altering frequency or ID");
  var rename=new FrequencyLibrary(Path.Combine(root,"renamed.json"));var p25=new SiteChannelData("P25",["P25","BEE00-348","RFSS 1 - Site 22"],"P25:BEE00-348:1:22",851187500,"00-0029","Voice channel","WACN BEE00; System 348; RFSS 1; Site 22; NAC 345");rename.SaveSiteChannels([p25]);var folder=rename.Items.Single(c=>c.IsFolder&&c.Name=="BEE00-348");rename.Upsert(folder with{Name="My named system"});var pp=rename.PreviewOrganization(rules,null,true,true,true);check(pp.Items.Any(c=>c.Id==folder.Id&&c.Name=="My named system")&&PathFor(pp.Items,pp.Items.Single(c=>!c.IsFolder)).Contains("My named system"),"Identity-bound custom system folder names are reused rather than replaced");
  var scopeOnly=OrganizationFields.From(new(){Protocols="DMR",SiteScope="DMR:DMR Tier III:Network 5:Site 1",Signaling="CC 6"});check(scopeOnly.KnownPath.SequenceEqual(new[]{"DMR","DMR Tier III","Network 5","Site 1"}),"Known system/site from imported channel scope is retained even when its signaling text only has color code");
  var borrowed=new FrequencyLibrary(Path.Combine(root,"manual-browse-folder.json"));var br=new FrequencyItem{IsFolder=true,Name="DMR"};var bv=new FrequencyItem{IsFolder=true,Name="Generic DMR",ParentId=br.Id};var bc=new FrequencyItem{IsFolder=true,Name="CC 1",ParentId=bv.Id};foreach(var f in new[]{br,bv,bc})borrowed.Upsert(f);borrowed.Upsert(generic with{ParentId=bc.Id});borrowed.ApplyOrganization(borrowed.PreviewOrganization(rules,null,true,true,true));borrowed.ApplyOrganization(borrowed.PreviewOrganization(rules with{Layout="Protocol"},null,true,true,true));check(borrowed.Items.Any(c=>c.Id==bc.Id&&c.BindingKey==""),"Reusing a user-created CC folder never takes ownership or deletes it during a later reorganization");
  var tampered=selectedDb.PreviewOrganization(rules,null,true,true,false);tampered.Items.RemoveAll(i=>i.Id==cap.Id);rejected=false;try{selectedDb.ApplyOrganization(tampered);}catch(IOException){rejected=true;}check(rejected,"Apply rejects a plan that deletes a channel");
  var now=DateTimeOffset.UtcNow;futureOnly.SaveDiscoveries([new(Guid.NewGuid(),315000000,"NFM",12500,10000,now,now,1,12)],"Synthetic receiver");check(futureOnly.Items.Single(c=>c.FrequencyHz==315000000).ParentId is {} rfParent&&futureOnly.Items.Single(c=>c.Id==rfParent).Name=="Unknown signal","New RF activity discoveries also use the saved organization rules");
  var manualFolder=new FrequencyItem{IsFolder=true,Name="My manual placement"};futureOnly.Upsert(manualFolder);var manual=Channel("Capacity Plus",454000000,"Custom named carrier") with{ParentId=manualFolder.Id};futureOnly.Upsert(manual);futureOnly.SaveSiteChannels([incoming with{Hz=454000000,Scope=manual.SiteScope}]);check(futureOnly.Items.Single(c=>c.Id==manual.Id).ParentId==manualFolder.Id,"Auto-save does not move a manually placed channel out of its custom folder");
  var cleanup=futureOnly.PreviewCleanup(true,true,false,0,0);check(!cleanup.Channels.Any(c=>c.IsFolder&&c.Name.StartsWith("Unassigned at")),"The older cleanup action respects configured organization instead of restoring placeholders");
  var savedFolders=new FrequencyLibrary(Path.Combine(root,"manual-non-dmr.json"));
  var fm=new FrequencyItem{IsFolder=true,Name="FM Radio"};
  var air=new FrequencyItem{IsFolder=true,Name="Air"};
  var airData=new FrequencyItem{IsFolder=true,Name="data",ParentId=air.Id};
  var airVoice=new FrequencyItem{IsFolder=true,Name="Voice",ParentId=air.Id};
  var mesh=new FrequencyItem{IsFolder=true,Name="mesh"};
  foreach(var f in new[]{fm,air,airData,airVoice,mesh})savedFolders.Upsert(f);
  var manualChannels=new[]{
   new FrequencyItem{Name="FM station",ParentId=fm.Id,FrequencyHz=102100000,Mode="WFM"},
   new FrequencyItem{Name="Mesh slot",ParentId=mesh.Id,FrequencyHz=906875000,Protocols=" unknown "},
   new FrequencyItem{Name="acars",ParentId=airData.Id,FrequencyHz=131550000,Mode="AM"},
   new FrequencyItem{Name="Signal 128.623 MHz",ParentId=airVoice.Id,FrequencyHz=128623000,Mode="AM",Tags="RF activity discovery"},
   new FrequencyItem{Name="Air monitor",FrequencyHz=128650000,Mode="AM",Protocols="Unknown"}
  };
  foreach(var c in manualChannels)savedFolders.Upsert(c);
  savedFolders.SaveDiscoveries([new(Guid.NewGuid(),315000000,"NFM",12500,10000,now,now,1,12)],"Synthetic receiver");
  var protectedPlan=savedFolders.PreviewOrganization(rules,null,true,true,true);
  check(manualChannels.All(c=>protectedPlan.Items.Single(i=>i.Id==c.Id)==c)&&
        protectedPlan.Changes.Count(c=>c.Action=="Held"&&c.Before==c.After)==manualChannels.Length,
   "Unidentified FM, mesh and aviation saves keep their names and folders, including an RF discovery filed manually");
  check(PathFor(protectedPlan.Items,protectedPlan.Items.Single(i=>i.FrequencyHz==315000000))=="Unknown signal",
   "Unfiled scanner discoveries can still use the Unknown signal folder during reorganization");
  savedFolders.ApplyOrganization(protectedPlan);
  var protectedCleanup=savedFolders.PreviewCleanup(true,true,false,0,0);
  check(manualChannels.All(c=>protectedCleanup.Channels.Single(i=>i.Id==c.Id)==c),
   "Saved-frequency cleanup also preserves unidentified entries with existing names and placement");
  var corrupt=selectedDb.PreviewOrganization(rules,null,true,true,false);var ix=corrupt.Items.FindIndex(c=>c.Id==generic.Id);corrupt.Items[ix]=corrupt.Items[ix] with{FrequencyHz=999999999};rejected=false;try{selectedDb.ApplyOrganization(corrupt);}catch(IOException){rejected=true;}check(rejected,"Apply rejects a plan that changes channel frequency");
  string bundle=JsonSerializer.Serialize(futureOnly.ExportDiscoveries());check(!bundle.Contains("FolderTemplate")&&!bundle.Contains("PreferKnownSites"),"Saving preferences stay local and are excluded from shared discovery bundles");
  futureOnly.ApplyOrganization(futureOnly.PreviewOrganization(rules,null,false,false,false));check(new FrequencyLibrary(futureOnly.LibraryPath).Organization==null,"Disabling future rules restores legacy automatic placement without reorganizing channels");
 }
 internal static string CheckCopy(string source)
 {
  string original=File.ReadAllText(source);string hash=SyncJson.Hash(original);string root=Path.Combine(Path.GetTempPath(),"mrs-organization-copy-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);string copy=Path.Combine(root,"copied-library.json");File.WriteAllText(copy,original);var db=new FrequencyLibrary(copy);var channels=db.Items.Where(c=>!c.IsFolder).ToDictionary(c=>c.Id);string records=JsonSerializer.Serialize(db.Records);var plan=db.PreviewOrganization(new(),null,true,true,true);db.ApplyOrganization(plan);var after=new FrequencyLibrary(copy);if(!channels.Keys.ToHashSet().SetEquals(after.Items.Where(c=>!c.IsFolder).Select(c=>c.Id))||JsonSerializer.Serialize(after.Records)!=records)throw new IOException("Copied-library identity/catalog preservation failed");foreach(var c in after.Items.Where(c=>!c.IsFolder)){var old=channels[c.Id];if((c with{Name=old.Name,ParentId=old.ParentId})!=old)throw new IOException("Copied-library metadata changed");}if(SyncJson.Hash(File.ReadAllText(source))!=hash)throw new IOException("Source library changed while checking its copy");return $"PASS: copied-library organization retained all {channels.Count} channel IDs, tuning/evidence/notes and catalog; original source unchanged. {plan.Changes.Count(c=>c.Action=="Held")} ambiguous entries held. No operational apply.";
 }

}
